module Valid =
  let bind r f =
    match r:
      case Ok x: f x
      case Error e: Error (String.upper e)
  let return_ x = Ok x
type Signup = { user: string, age: int }
let parseForm user age =
  Valid {
    let! name = if String.len user > 1 then Ok user else Error "short name"
    let! years = Option.toResult "bad age" (String.toInt age)
    let! adult = if years >= 20 then Ok years else Error "too young"
    return Signup { user = name, age = adult }
  }
print (parseForm "ada" "26")
print (parseForm "a" "30", parseForm "bob" "x")

