let summarize xs =
  let mut lo = 1000
  let mut hi = -1000
  let mut total = 0
  let visit x =
    lo <- min lo x
    hi <- max hi x
    total <- total + x
  List.iter visit xs
  f"lo={lo} hi={hi} total={total}"
